import 'dart:async'; import 'package:flutter/material.dart'; import 'package:go_router/go_router.dart'; class SplashPage extends StatefulWidget{const SplashPage({super.key});@override State<SplashPage> createState()=>_SplashPageState();} class _SplashPageState extends State<SplashPage>{Timer? t;@override void initState(){super.initState();t=Timer(const Duration(milliseconds:1200),(){if(mounted)context.go('/onboarding');});}@override void dispose(){t?.cancel();super.dispose();}@override Widget build(BuildContext c)=>Scaffold(body:Center(child:Column(mainAxisSize:MainAxisSize.min,children:[Icon(Icons.visibility_outlined,size:72,color:Theme.of(c).colorScheme.primary),const SizedBox(height:16),Text('NewVision',style:Theme.of(c).textTheme.headlineMedium),const SizedBox(height:20),const CircularProgressIndicator()])));}}